#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 long long maxOutput(int n,vector<vector<int>>& edges,vector<int>& price){
  vector<vector<int>> g(n);for(auto &e:edges){g[e[0]].push_back(e[1]);g[e[1]].push_back(e[0]);}
  long long ans=0;
  function<pair<long long,long long>(int,int)> dfs=[&](int u,int p)->pair<long long,long long>{
   long long include=price[u],exclude=0;
   for(int v:g[u])if(v!=p){
    auto child=dfs(v,u);
    ans=max(ans,max(include+child.second,exclude+child.first));
    include=max(include,child.first+price[u]);
    exclude=max(exclude,child.second+price[u]);
   }
   return {include,exclude};
  };
  dfs(0,-1);return ans;
 }
};
